function validate([envelopes]) {
  if (!Array.isArray(envelopes) || envelopes.length < 1 || envelopes.length > 100000) return 'envelopes needs 1 to 10^5 envelopes.';
  for (const e of envelopes) {
    if (!Array.isArray(e) || e.length !== 2) return 'Each envelope is a pair [w, h].';
    if (!e.every(v => Number.isInteger(v) && v >= 1 && v <= 100000)) return 'Widths and heights are integers from 1 to 10^5.';
  }
  return null;
}

