function maxEnvelopes(envelopes) {
  envelopes.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const tails = [];

  for (const [, height] of envelopes) {
    let left = 0;
    let right = tails.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (tails[mid] < height) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    tails[left] = height;
  }
  return tails.length;
}

