function maxEnvelopes(envelopes) {
  // Longest chain by quadratic DP over envelopes ordered by width.
  const list = envelopes.map(e => [e[0], e[1]]).sort((a, b) => a[0] - b[0]);
  const chain = new Array(list.length).fill(1);
  let best = 0;
  for (let i = 0; i < list.length; i++) {
    for (let j = 0; j < i; j++) {
      if (list[j][0] < list[i][0] && list[j][1] < list[i][1]) chain[i] = Math.max(chain[i], chain[j] + 1);
    }
    best = Math.max(best, chain[i]);
  }
  return best;
}

