function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 9);
    const top = int(1, 6);
    return [Array.from({ length: n }, () => [int(1, top), int(1, top)])];
  }
  const n = 2000;
  const mode = int(0, 2);
  if (mode === 0) return [Array.from({ length: n }, () => [int(1, 100000), int(1, 100000)])];
  if (mode === 1) {
    // Mostly increasing along a diagonal with noise, so long chains exist.
    return [Array.from({ length: n }, (_, i) => [Math.min(100000, 1 + i * 40 + int(0, 300)), Math.min(100000, 1 + i * 40 + int(0, 300))])];
  }
  // Few distinct widths: many envelopes share a width and must not stack.
  return [Array.from({ length: n }, () => [int(1, 50), int(1, 100000)])];
}
